@keyframes art-light-breathe { from { opacity:.45; transform:translateX(-2%); } to { opacity:.95; transform:translateX(2%); } }
@keyframes art-haze-drift { from { transform:translateX(-3%); opacity:.3; } to { transform:translateX(3%); opacity:.8; } }
@keyframes art-water-glint { from { opacity:.035; transform:translateX(-.4%); } to { opacity:.16; transform:translateX(.4%); } }
@keyframes art-star-breathe { from { opacity:.08; } to { opacity:.35; } }
@media(prefers-reduced-motion:reduce) { .scene-air * { animation:none !important; } }

/* Quiet editorial structure and legible secondary reading. */
.reading-home.is-display .atmosphere-shade { background:radial-gradient(ellipse 68% 43% at 50% 48%,#07060aeb 0%,#07060ac4 55%,#07060a55 100%),linear-gradient(0deg,#07060a99,transparent 40%); }
.foot { font-size:14px; line-height:1.6; }
.faith-doc { max-width:52rem; margin-inline:auto; }
.faith-heading { display:grid; grid-template-columns:1fr 1fr; align-items:center; gap:24px; padding-bottom:36px; margin-bottom:36px; border-bottom:1px solid var(--line); }
.faith-heading img { width:100%; height:300px; object-fit:cover; object-position:75% center; mask-image:linear-gradient(90deg,transparent,#000 22%,#000 85%,transparent); }
.faith-heading .hero-kicker { font-size:11px; color:var(--fire); }
.faith-heading h1 { margin:12px 0 24px; }
.faith-heading .faith-lead { margin:0; }
.faith-doc > p { max-width:58ch; font-size:19px; line-height:1.72; font-weight:400; }
.faith-doc h2 { margin-top:44px; }
.doubt-copy p { color:#c8c0b3; font-size:19px; }
.source-columns .sources a { font-size:17px; line-height:1.5; }
.source-columns .sources span { font-size:15px; line-height:1.6; }
@media(max-width:700px) {
  .faith-heading { grid-template-columns:1fr; gap:18px; padding-bottom:20px; margin-bottom:28px; }
  .faith-heading img { height:160px; object-position:center 60%; mask-image:linear-gradient(90deg,transparent,#000 8%,#000 92%,transparent); }
  .faith-doc > p { font-size:18px; }
  .doubt-hero { min-height:0; padding:52px 0 36px; }
  .doubt-hero h1 { max-width:11ch; font-size:clamp(50px,13vw,72px); line-height:1; letter-spacing:-.04em; }
  .doubt-lead { max-width:34ch; font-size:25px; line-height:1.42; }
  .doubt-aperture { background:radial-gradient(ellipse at 90% 10%,#c1a1691a,transparent 65%),#08090b; opacity:1; }
  .doubt-aperture::after { inset:8% -50% 60% 35%; border-radius:50%; transform:rotate(-25deg); opacity:.35; }
  .doubt-paths { display:grid; gap:6px; margin-top:28px; }
  .doubt-paths a { align-items:center; }
  .doubt-essay,.source-ledger { padding-block:48px; }
  .doubt-essay { gap:26px; }
  .doubt-essay h2,.source-ledger h2 { font-size:42px; line-height:1.06; }
  .doubt-copy p { font-size:18px; line-height:1.7; }
  .source-columns { gap:32px; margin-top:30px; }
}

